# vtb.R -- VTB United League wrappers over two keyless public JSON backends of vtb-league.com, at parity with
# sportsdataverse-py sportsdataverse/basketball/vtb (origin/main e3d232ebc9): api.vtb-league.com/v2 (vtb_league_*, the
# schedule API) and Infobasket, the Russian basketball federation's stats platform (org.infobasket.su,
# vtb_infobasket_*). Transport, season mapping, personal-data scrub and refusals: R/vtb_runtime.R; frames:
# R/vtb_parsers.R; columns and code tables: R/vtb_tables.R. Generated by a scratch generator from the sportsdataverse-py
# endpoint YAMLs, returns schemas and manual_column_descriptions.yaml; regenerate rather than hand-edit.

# The @details of every vtb topic that shares the vtb_infobasket_seasons() notes (roxygen @eval .intl_details()).
.vtb_infobasket_seasons_details <- c(
  "* Source: the VTB United League (vtb-league.com) and Infobasket, the Russian basketball federation's stats",
  "  platform (org.infobasket.su). No account, key or payment is needed.",
  "* Unofficial and unsupported: both hosts are keyless public JSON backends of vtb-league.com. No terms of use are",
  "  published; robots.txt is a 404 on api.vtb-league.com and org.infobasket.su (no rules; vtb-league.com disallows",
  "  only /wp/wp-admin/). The runtime waits at least 1 s before every request, retries included, and honours",
  "  Retry-After on 429 / 503. No key, cookie or proxy is used.",
  "* Seasons are END years (2026 = 2025-26) on both backends. Infobasket keys everything by competition id:",
  "  vtb_infobasket_seasons maps the END year to the season-level CompID, and the season-keyed wrappers do that mapping",
  "  for you. CompID means three things: a season (50714), a stage below it (50720 regular season, 54281 playoff;",
  "  stage-level wrappers take the stage id from vtb_infobasket_comp_issue) and, in the player season stats, an END",
  "  year.",
  "* Ids: the v2 matchId is the Infobasket GameID, the v2 teamId the Infobasket TeamID and the v2 venueId the",
  "  Infobasket ArenaId. team_id is the key on every team route; comp_team_id (a registration in one stage) and the",
  "  club-record id of the team page are other key spaces. person_id is one person across clubs and seasons.",
  "* Errors are HTTP 200: an unknown id answers \\{MessageType, Message\\}, an unknown game the string 'BadRequest'; both",
  "  are `hoopR_asset_fetch` (a failed fetch), never an empty frame. A body for another game, person, team, competition",
  "  or season than the one asked for is `hoopR_asset_fetch` too, as is a game that is not final (box score, plays and",
  "  header need GameStatus 1) and a partial GetTeamStats page. An empty list is `hoopR_no_data`.",
  "* Coverage: calendars and box scores from 2009-10; play-by-play and shot x/y from 2022-23 only (earlier games give",
  "  an empty pbp frame), officials in the line-ups from 2022-23. Shot x/y are decimetres from the basket centre",
  "  (orientation unverified). Counting statistics are null instead of 0 on the wire (the parsers fill 0), percentages",
  "  and averages are comma-decimal strings (the parsers return floats), the paint statistics are broken and dropped,",
  "  and dates come in three encodings (the parsers return ISO strings; .NET instants as Moscow time with its +03:00",
  "  offset).",
  "* Personal data: the runtime removes licence numbers, contact and operator-account fields for everyone and the birth",
  "  dates, birth years and ages of coaches, referees and other officials from every body. Players' public bio (birth",
  "  date, height, weight, nationality) is kept.",
  "* Other tags (vtbyouth, wbc, wpremier, rfb) answer through the tag argument; only vtb was captured. The team routes",
  "  key on the END-year season (sportsdataverse-py also lets a caller pass a stage CompID through params; the R wrappers do not).",
  "* Errors are classed conditions, all inheriting `hoopR_error`: `hoopR_no_data` (HTTP 404, or the host has nothing",
  "  for the request: an empty list, a v2 season with no rows, a season without team totals), `hoopR_bad_request` (a",
  "  malformed id or league slug, a lang other than en or ru, or a season the competition tag does not have) and",
  "  `hoopR_asset_fetch` (any other non-2xx, an empty or non-JSON body, an error envelope or string, a game that is not",
  "  final or a stub, a partial or possibly truncated page, or a body for another game, person, team, competition,",
  "  league or season). HTTP 500 is retried (neither host answers 500 for an unknown id). Wrappers raise; they never",
  "  warn and return empty."
)

#' @title
#' **Get VTB Infobasket Seasons**
#' @description
#' Season END year -> season-level CompID for a competition tag (the table every season-keyed wrapper maps with).
#'
#' Endpoint: `GET https://org.infobasket.su/Comp/GetSeasonsForTag`
#' @param tag Competition tag scoping the profile: vtb (VTB United League, default), vtbyouth, wbc, wpremier or rfb.
#'   The season table is read for this tag.
#' @eval .returns_rd("vtb_infobasket_seasons", inline = FALSE, unit = "season")
#' @eval .intl_details(.vtb_infobasket_seasons_details, full = TRUE)
#' @examples
#' \donttest{
#'   try(vtb_infobasket_seasons())
#' }
#' @export
#' @concept VTB Functions
#' @seealso [family_vtb] lists every function in this family.
vtb_infobasket_seasons <- function(tag = "vtb") {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  raw <- .vtb_ib_get("/Comp/GetSeasonsForTag", ids = list(), query = list(format = "json", tag = tag), call = call)
  .vtb_out("vtb_infobasket_seasons", raw, "VTB Infobasket Seasons from org.infobasket.su")
}

