#' @description
#' Standings of one stage (a round-robin stage such as the regular season), one row per team.
#'
#' Endpoint: `GET https://org.infobasket.su/Widget/CompTeamResults/{comp_id}`
#' @param comp_id Stage CompID (comp_id in vtb_infobasket_comp_issue), not a season id and not an END year, e.g. 50720
#'   (Regular Season 2025-26) or 54281 (Playoff 2025-26).
#' @eval .returns_rd("vtb_infobasket_standings", inline = FALSE, unit = "team in the standings")
#' @eval .intl_details(.vtb_infobasket_seasons_details)
#' @examples
#' \donttest{
#'   try(vtb_infobasket_standings(comp_id = 50720))
#' }
#' @export
#' @concept VTB Functions
#' @seealso [family_vtb] lists every function in this family.
vtb_infobasket_standings <- function(comp_id) {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  raw <- .vtb_ib_get(
    "/Widget/CompTeamResults/{comp_id}", ids = list(comp_id = comp_id),
    query = list(format = "json"),
    call = call
  )
  .vtb_out("vtb_infobasket_standings", raw, "VTB Infobasket Standings from org.infobasket.su")
}

