#' @seealso [family_vtb] lists every function in this family.
vtb_infobasket_player_game_log <- function(person_id, season, team, filter = 1, tag = "vtb") {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  raw <- .vtb_ib_get(
    "/Widget/PlayerStats/{person_id}", ids = list(person_id = person_id),
    query = list(format = "json", season = season, team = team, filter = filter, tag = tag),
    call = call
  )
  .vtb_out("vtb_infobasket_player_game_log", raw, "VTB Infobasket Player Game Log from org.infobasket.su")
}

