#' Endpoint: `GET https://org.infobasket.su/Widget/TeamStats/{team_id}`
#' @param team_id Infobasket TeamID (team_id in the calendar, a box score or the v2 matches), e.g. 2650 (Lokomotiv
#'   Kuban).
#' @param season Season END year (2026 = 2025-26); the wrapper maps it to the season-level Infobasket CompID with
#'   vtb_infobasket_seasons (one extra request per tag, cached). Required.
#' @param lang Label language (en or ru). Most bodies carry both languages whatever is asked; the leader categories'
#'   labels follow it.
#' @param tag Competition tag scoping the profile: vtb (VTB United League, default), vtbyouth, wbc, wpremier or rfb.
#'   The season table is read for this tag.
#' @eval .returns_rd("vtb_infobasket_team_season_stats", inline = FALSE, unit = "club-season")
#' @eval .intl_details(.vtb_infobasket_seasons_details, "vtb_infobasket_team_season_stats(season = 2026, team_id = 2650)")
#' @export
#' @concept VTB Functions
#' @seealso [family_vtb] lists every function in this family.
vtb_infobasket_team_season_stats <- function(team_id, season, lang = "en", tag = "vtb") {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  .vtb_lang_arg(lang, call = call)
  raw <- .vtb_ib_get(
    "/Widget/TeamStats/{team_id}", ids = list(team_id = team_id),
    query = list(format = "json", season = season, lang = lang, tag = tag),
    call = call
  )
  .vtb_out("vtb_infobasket_team_season_stats", raw, "VTB Infobasket Team Season Stats from org.infobasket.su")
}

