#' @title
#' **Get VTB League Leagues**
#' @description
#' The leagues served by the API: vtb, vtbyouth, wbc.
#'
#' Endpoint: `GET https://api.vtb-league.com/v2/leagues`
#' @eval .returns_rd("vtb_league_leagues", inline = FALSE, unit = "competition")
#' @details
#' * Source, access, seasons, ids and the error classes: see the notes of [vtb_infobasket_seasons()].
#' * v2 pages: meta.count is the rows returned (not a total), page is ignored and the default limit is 20, so the
#'   matches wrapper asks for 1000 and refuses a body whose count reaches its limit. The API lists new seasons only
#'   (from 2024-25; vtb: 2025-2027, wbc: 2026-2027): earlier years answer no rows (`hoopR_no_data`).
#' @examples
#' \donttest{
#'   try(vtb_league_leagues())
#' }
#' @export
#' @concept VTB Functions
#' @seealso [family_vtb] lists every function in this family.
vtb_league_leagues <- function() {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  raw <- .vtb_league_get(query = list(), call = call)
  .vtb_out("vtb_league_leagues", raw, "VTB League Leagues from api.vtb-league.com")
}

#' @title
#' **Get VTB League Seasons**
#' @description
#' The seasons the API serves for one league (new seasons only, from 2024-25).
#'
#' Endpoint: `GET https://api.vtb-league.com/v2/leagues/{league_slug}/seasons`
#' @param league_slug League slug (league in vtb_league_leagues): vtb (VTB United League), vtbyouth (youth league) or
#'   wbc (WINLINE Basket Cup).
#' @eval .returns_rd("vtb_league_seasons", inline = FALSE, unit = "season")
#' @inherit vtb_league_leagues details
#' @examples
#' \donttest{
#'   try(vtb_league_seasons(league_slug = "vtb"))
#' }
#' @export
#' @concept VTB Functions
#' @seealso [family_vtb] lists every function in this family.
vtb_league_seasons <- function(league_slug) {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  raw <- .vtb_league_get(league_slug = league_slug, query = list(), call = call)
  .vtb_out("vtb_league_seasons", raw, "VTB League Seasons from api.vtb-league.com")
}

#' @title
#' **Get VTB League Matches**
#' @description
#' Every match of one league-season (schedule, scores, quarter points, venue), in one request.
#'
#' Endpoint: `GET https://api.vtb-league.com/v2/leagues/{league_slug}/seasons/{season}/matches`
#' @param league_slug League slug (league in vtb_league_leagues): vtb (VTB United League), vtbyouth (youth league) or
#'   wbc (WINLINE Basket Cup).
#' @param season Season END year (2026 = 2025-26). The v2 API holds 2025 onwards (vtb: 2025-2027; wbc: 2026-2027);
#'   earlier years answer no rows.
#' @eval .returns_rd("vtb_league_matches", inline = FALSE, unit = "game")
#' @inherit vtb_league_leagues details
#' @examples
#' \donttest{
#'   try(vtb_league_matches(league_slug = "vtb", season = 2026))
#' }
#' @export
#' @concept VTB Functions
#' @seealso [family_vtb] lists every function in this family.
vtb_league_matches <- function(league_slug, season) {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  raw <- .vtb_league_get(league_slug = league_slug, season = season, query = list(limit = 1000), call = call)
  .vtb_out("vtb_league_matches", raw, "VTB League Matches from api.vtb-league.com")
}
